use rand::Rng;
use serde::Serialize;
use std::{
    collections::{BTreeMap, BTreeSet},
    sync::Arc,
};

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
pub enum SeedPolicy {
    World,
    Unseeded,
}
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
pub enum GeneratorKind {
    Pirate,
    Snake,
    Sprite,
    Undead,
    Abyss,
    Trench,
    Spider,
    Lab,
    Jungle,
    Manor,
    Beach,
    Davy,
    Tomb,
}
impl GeneratorKind {
    fn parse(s: &str) -> Result<Self> {
        Ok(match s {
            "pirate" => Self::Pirate,
            "snake" => Self::Snake,
            "sprite" => Self::Sprite,
            "undead" => Self::Undead,
            "abyss" => Self::Abyss,
            "trench" => Self::Trench,
            "spider" => Self::Spider,
            "lab" => Self::Lab,
            "jungle" => Self::Jungle,
            "manor" => Self::Manor,
            "beach" => Self::Beach,
            "davy" => Self::Davy,
            "tomb" => Self::Tomb,
            _ => bail!("unknown geometry generator {s}"),
        })
    }
}
#[derive(Clone, Copy, Debug, Serialize)]
pub struct Span {
    pub min: u32,
    pub max: u32,
}
#[derive(Clone, Debug, Serialize)]
pub struct Tile {
    pub ground: Option<u8>,
    pub object: Option<u16>,
    pub clear_object: bool,
}
#[derive(Clone, Debug, Serialize)]
pub struct ProbabilityTile {
    pub probability: f64,
    pub tile: Tile,
}
#[derive(Clone, Debug, Serialize)]
pub struct RoleTile {
    pub common: Tile,
    pub choices: Vec<ProbabilityTile>,
}
impl RoleTile {
    fn deterministic(&self) -> bool {
        self.choices.is_empty()
            || (self.choices.iter().filter(|c| c.probability > 0.).count() == 1
                && self.choices.iter().map(|c| c.probability).sum::<f64>() == 1.)
    }
    /// Apply common layers once; a residual draw allocates no choice layers.
    pub fn choose(&self, draw: f64) -> Result<Option<&Tile>> {
        ensure!(
            draw.is_finite() && (0.0..1.0).contains(&draw),
            "tile draw must be finite in [0,1)"
        );
        let mut cumulative = 0.;
        for choice in &self.choices {
            cumulative += choice.probability;
            if draw < cumulative {
                return Ok(Some(&choice.tile));
            }
        }
        Ok(None)
    }
}
